Recorder — write carefully:

```ts
interface WireFrame {
  type: string;
  code?: string;
  message?: string;
  sessionId?: string;
  resumed?: boolean;
  entryCount?: number;
  index?: number;
  entry?: SessionEntry;
  conversations?: ConversationSummary[];
}

interface ConversationSummary {
  sessionId: string;
  createdAt: string;
  updatedAt: string;
  entryCount: number;
}

const listener = (client: WebSocket) => {
  const frames: WireFrame[] = [];
  client.on('message', raw => frames.push(JSON.parse(String(raw)) as WireFrame));
  return {
    frames,
    next: (label: string, matches: (frame: WireFrame) => boolean, withinMs = 2000) =>
      new Promise<WireFrame>((resolve, reject) => {
        const arrived = frames.find(matches);
        if (arrived) {resolve(arrived); return;}
        const timer = setTimeout(() => {
          const seen = frames.map(frame => frame.type).join(', ') || 'nothing';
          reject(new Error(`no ${label} arrived within ${withinMs}ms; the socket received: ${seen}`));
        }, withinMs);
        const poll = setInterval(() => {
          const arrived = frames.find(matches);
          if (arrived) {clearTimeout(timer); clearInterval(poll); resolve(arrived);}
        }, 5);
        setTimeout(() => clearInterval(poll), withinMs + 50);
      }),
  };
};
```

Polling every 5ms is simpler than waiter queues and plenty. Timer rejects at withinMs. Fine. Slight redundancy ok.

