  it('rejoins a conversation by an id taken from a list row, through the existing resume path', async () => {
    const base = await startEngine({
      store: new InMemorySessionStore(),
      history: {enabled: true},
      resume: {enabled: true},
    });
    const first = await openConnection(base);
    send(first.client, {type: 'user_message', content: 'hello'});
    await first.wire.next('the turn to finish', frame => frame.type === 'stream_end');

    send(first.client, {type: 'list_conversations'});
    const listed = await first.wire.next('a conversation_list frame', frame => frame.type === 'conversation_list');
    const row = listed.frame.conversations?.[0]?.sessionId ?? '';

    first.client.close();
    const again = await openConnection(`${base}?sessionId=${row}`);
    await again.wire.next('the replayed user entry', frame => frame.type === 'entry_upsert' && frame.entry?.role === 'user');
    await again.wire.next(
      'the replayed assistant entry',
      frame => frame.type === 'entry_upsert' && frame.entry?.role === 'assistant'
    );
    await settle(100);

    expect({
      rowFromList: row,
      rejoined: again.sessionId,
      resumed: again.connected.resumed,
      entryCount: again.connected.entryCount,
      replay: again.wire.frames.filter(frame => frame.type === 'entry_upsert').map(frame => frame.entry?.role),
      reconnectErrors: again.wire.frames.filter(frame => frame.type === 'error').map(frame => frame.code),
    }).toEqual({
      rowFromList: first.sessionId,
      rejoined: first.sessionId,
      resumed: true,
      entryCount: 2,
      replay: ['user', 'assistant'],
      reconnectErrors: [],
    });
  });
});

