    await eventually(() => wss.clients.size === 0);
    await hal.stop();
  }
});

describe('a conversation list over the WebSocket', () => {
  it('answers list_conversations with the connection\'s own conversations, newest first, and pages them with limit and before', async () => {
    const store = new InMemorySessionStore();
    const listForCalls = recordListFor(store);
    store.create('conv-old', 'user-1');
    await settle(15);
    store.create('conv-mid', 'user-1');
    const base = await startEngine({store, history: {enabled: true}});
    const {client, wire, sessionId} = await openConnection(base);

    send(client, {type: 'list_conversations'});
    const listed = await wire.next('a conversation_list frame', frame => frame.type === 'conversation_list');
    const [head] = listed.frame.conversations ?? [];
    send(client, {
      type: 'list_conversations',
      limit: 1,
      before: {updatedAt: head?.updatedAt, sessionId: head?.sessionId},
    });
    const page = await wire.next(
      'the page that follows the cursor',
      frame => frame.type === 'conversation_list' && frame !== listed.frame
    );
    await settle(200);

    expect({
      listed: (listed.frame.conversations ?? []).map(row => row.sessionId),
      firstPage: listed.frame.conversations,
      paged: (page.frame.conversations ?? []).map(row => row.sessionId),
      listFrames: wire.frames.filter(frame => frame.type === 'conversation_list').length,
      streamEnds: wire.frames.filter(frame => frame.type === 'stream_end').length,
      errors: wire.frames.filter(frame => frame.type === 'error').map(frame => frame.code),
      bareCall: listForCalls[0],
      pagedCall: listForCalls[1],
    }).toEqual({
      listed: [sessionId, 'conv-mid', 'conv-old'],
      firstPage: store.listFor('user-1').map(asIso),
      paged: ['conv-mid'],
      listFrames: 2,
      streamEnds: 0,
      errors: [],
      bareCall: {userId: 'user-1', options: {limit: undefined, before: undefined}},
      pagedCall: {
        userId: 'user-1',
        options: {limit: 1, before: {updatedAt: head?.updatedAt, sessionId: head?.sessionId}},
      },
    });
  });

  it('answers a frame naming another user with the connecting user\'s own list, asking the store for the connection\'s user', async () => {
    const store = new InMemorySessionStore();
    const listForCalls = recordListFor(store);
    store.create('conv-of-user-2', 'user-2');
    await settle(15);
    store.create('conv-of-user-1', 'user-1');
    const base = await startEngine({store, history: {enabled: true}});
    const {client, wire, sessionId} = await openConnection(base);

    send(client, {type: 'list_conversations', userId: 'user-2'});
    const listed = await wire.next('a conversation_list frame', frame => frame.type === 'conversation_list');
    await settle(100);

    expect({
      askedFor: listForCalls.map(call => call.userId),
      rows: (listed.frame.conversations ?? []).map(row => row.sessionId),
    }).toEqual({
      askedFor: ['user-1'],
      rows: [sessionId, 'conv-of-user-1'],
    });
  });

  it('answers a history that is off, a store that cannot list, and a store that fails with one error frame and never an empty list', async () => {
    const disabled = await errorAnswer(await startEngine({store: new InMemorySessionStore()}));

    const bare: SessionStore = new InMemorySessionStore();
    bare.listFor = undefined;
    const cannotList = await errorAnswer(await startEngine({store: bare, history: {enabled: true}}));

    const failing = new InMemorySessionStore();
    const held = failing.create('conv-private', 'user-1');
    appendEntry(held, createUserEntry('very-private-note'));
    failing.listFor = () => Promise.reject(new Error('list failed: conversations collection unreachable'));
    const failingBase = await startEngine({store: failing, history: {enabled: true}});
    const connection = await openConnection(failingBase);
    send(connection.client, {type: 'list_conversations'});
    const failed = await connection.wire.next('an error frame', frame => frame.type === 'error');
    send(connection.client, {type: 'ping', timestamp: 4321});
    const pong = await connection.wire.next('a pong frame', frame => frame.type === 'pong');
    await settle(100);

    expect({
      disabled,
      cannotList,
      failedCode: failed.frame.code,
      contentLeaked:
        String(failed.frame.message).includes('very-private-note') ||
        String(failed.frame.message).includes('conversations collection') ||
        JSON.stringify(errors).includes('very-private-note'),
      loggedWithSessionId: errors.some(line => String(line.sessionId) === connection.sessionId),
      framesAfterFailure: connection.wire.frames.map(frame => frame.type),
      pongEchoed: pong.frame.timestamp,
    }).toEqual({
      disabled: {frames: ['connected', 'error'], code: 'UNSUPPORTED'},
      cannotList: {frames: ['connected', 'error'], code: 'UNSUPPORTED'},
      failedCode: 'SERVER_ERROR',
      contentLeaked: false,
      loggedWithSessionId: true,
      framesAfterFailure: ['connected', 'error', 'pong'],
      pongEchoed: 4321,
    });
  });

  it('answers list_conversations while a turn on the same session is still streaming, before that turn ends', async () => {
    const gate = deferred();
    try {
      const streaming: ChatOrchestrator = {
        processMessage: async () => 'late',
        async *processMessageStream(): AsyncGenerator<MessageChunk> {
          yield {type: 'text', text: 'half'};
          await gate.until;
          yield {type: 'stop', stopReason: 'end_turn'};
        },
      };
      const base = await startEngine({
        store: new InMemorySessionStore(),
        history: {enabled: true},
        orchestrator: streaming,
      });
      const {client, wire, sessionId} = await openConnection(base);

      send(client, {type: 'user_message', content: 'a long question'});
      await wire.next('the turn to start', frame => frame.type === 'entry_upsert');
      send(client, {type: 'list_conversations'});
      const listed = await wire.next(
        'a conversation_list frame while the turn is still streaming',
        frame => frame.type === 'conversation_list'
      );
      const turnStillStreaming = !wire.frames.some(frame => frame.type === 'stream_end');
      gate.release();
      await wire.next('the turn to end', frame => frame.type === 'stream_end');

      expect({
        answered: (listed.frame.conversations ?? []).map(row => row.sessionId),
        answeredBeforeTurnEnd: turnStillStreaming,
        order: wire.frames
          .map(frame => frame.type)
          .filter(type => type === 'conversation_list' || type === 'stream_end' || type === 'error'),
      }).toEqual({
        answered: [sessionId],
        answeredBeforeTurnEnd: true,
        order: ['conversation_list', 'stream_end'],
      });
    } finally {
      gate.release();
    }
  });

  it('validates the frame whether or not history is on, refusing a bad limit or before with the field named', async () => {
    const base = await startEngine({store: new InMemorySessionStore(), history: {enabled: true}});
    const {client, wire} = await openConnection(base);
    const cases: Array<[Record<string, unknown>, string]> = [
      [{type: 'list_conversations', limit: 0}, 'limit'],
      [{type: 'list_conversations', limit: 201}, 'limit'],
      [{type: 'list_conversations', limit: 1.5}, 'limit'],
      [{type: 'list_conversations', limit: '10'}, 'limit'],
      [{type: 'list_conversations', before: 'not a date'}, 'before'],
      [{type: 'list_conversations', before: {updatedAt: '2026-03-01T00:00:00.000Z'}}, 'before|sessionId'],
      [{type: 'list_conversations', before: {sessionId: 'conv-old'}}, 'before|updatedAt'],
    ];
    const refusals: Array<{code: string; named: boolean}> = [];
    let cursor = 0;
    for (const [frame, field] of cases) {
      send(client, frame);
      const answered = await wire.next(`an error for ${JSON.stringify(frame)}`, frame => frame.type === 'error', cursor);
      cursor = answered.after;
      refusals.push({code: answered.frame.code ?? '', named: new RegExp(field).test(String(answered.frame.message))});
    }
    await settle(100);

    const offBase = await startEngine({store: new InMemorySessionStore()});
    const off = await openConnection(offBase);
    send(off.client, {type: 'list_conversations', limit: 0});
    const offAnswered = await off.wire.next('an error with history off', frame => frame.type === 'error');
    await settle(100);

    expect({
      refusals,
      historyOnList: wire.frames.some(frame => frame.type === 'conversation_list'),
      offCode: offAnswered.frame.code,
      offNamed: /limit/.test(String(offAnswered.frame.message)),
    }).toEqual({
      refusals: Array.from({length: cases.length}, () => ({code: 'INVALID_MESSAGE', named: true})),
      historyOnList: false,
      offCode: 'INVALID_MESSAGE',
      offNamed: true,
    });
  });

  it('rejoins a conversation by an id taken from a list row, through the existing resume path', async () => {
    const base = await startEngine({
      store: new InMemorySessionStore(),
      history: {enabled: true},
      resume: {enabled: true},
    });
    const first = await openConnection(base);
    send(first.client, {type: 'user_message', content: 'hello'});
    await first.wire.next('the turn to finish', frame => frame.type === 'stream_end');

    send(first.client, {type: 'list_conversations'});
    const listed = await first.wire.next('a conversation_list frame', frame => frame.type === 'conversation_list');
    const row = listed.frame.conversations?.[0]?.sessionId ?? '';

    first.client.close();
    const again = await openConnection(`${base}?sessionId=${row}`);
    await again.wire.next('the replayed user entry', frame => frame.type === 'entry_upsert' && frame.entry?.role === 'user');
    await again.wire.next(
      'the replayed assistant entry',
      frame => frame.type === 'entry_upsert' && frame.entry?.role === 'assistant'
    );
    await settle(100);

    expect({
      rowFromList: row,
      rejoined: again.sessionId,
      resumed: again.connected.resumed,
      entryCount: again.connected.entryCount,
      replay: again.wire.frames.filter(frame => frame.type === 'entry_upsert').map(frame => frame.entry?.role),
      reconnectErrors: again.wire.frames.filter(frame => frame.type === 'error').map(frame => frame.code),
    }).toEqual({
      rowFromList: first.sessionId,
      rejoined: first.sessionId,
      resumed: true,
      entryCount: 2,
      replay: ['user', 'assistant'],
      reconnectErrors: [],
    });
  });
});

